int fimc_is_hw_i2c_lock(struct fimc_is_interface *this,
	u32 instance, int i2c_clk, bool lock)
{
	int ret;
	struct fimc_is_msg msg, reply;

	dbg_interface("i2c_lock(%d)\n", instance);

	msg.id = 0;
	msg.command = HIC_I2C_CONTROL_LOCK;
	msg.instance = instance;
	msg.group = 0;
	msg.param1 = lock;
	msg.param2 = i2c_clk;
	msg.param3 = 0;
	msg.param4 = 0;

	ret = fimc_is_set_cmd(this, &msg, &reply);

	return ret;
}

int fimc_is_hw_isp_i2c_control(struct fimc_is_interface *this,
	u32 instance, u32 ch)
{
	int ret;
	struct fimc_is_msg msg, reply;

	info("isp i2c control(instance %d, ch %d)\n", instance, ch);

	msg.id = 0;
	msg.command = HIC_ISP_I2C_CONTROL;
	msg.instance = instance;
	msg.group = 0;
	msg.param1 = ch;
	msg.param2 = 0;
	msg.param3 = 0;
	msg.param4 = 0;

	ret = fimc_is_set_cmd(this, &msg, &reply);

	return ret;
}

