import capstone, struct, sys, re
d=open('/tmp/fw.bin','rb').read()
md=capstone.Cs(capstone.CS_ARCH_ARM, capstone.CS_MODE_THUMB)
targets={int(x,16) for x in sys.argv[1:]}
res={t:[] for t in targets}
N=0x240000
for a in range(0,N,2):
    if a+4>len(d): break
    try:
        ins=list(md.disasm(d[a:a+4], a, count=1))
    except Exception:
        continue
    if not ins: continue
    i=ins[0]
    m=i.mnemonic; o=i.op_str
    val=None
    if m.startswith('adr'):
        mm=re.search(r'#(0x[0-9a-f]+|[0-9]+)',o)
        if mm:
            imm=int(mm.group(1),0)
            val=((a+4)&~3)+imm
    elif m.startswith('add') and 'pc' in o:
        mm=re.search(r'#(0x[0-9a-f]+|[0-9]+)',o)
        if mm:
            imm=int(mm.group(1),0)
            val=((a+4)&~3)+imm
    elif m.startswith('ldr') and 'pc' in o and '#' in o:
        mm=re.search(r'#(-?0x[0-9a-f]+|-?[0-9]+)',o)
        if mm:
            imm=int(mm.group(1),0)
            p=((a+4)&~3)+imm
            if 0<=p<=len(d)-4:
                v=struct.unpack_from('<I',d,p)[0]
                if v in targets:
                    res.setdefault(v,[]).append((a,'lit@%x'%p,m,o))
    if val in targets:
        res.setdefault(val,[]).append((a,'',m,o))
for t in sorted(targets):
    print(hex(t), d[t:t+40].split(b'\0')[0] if t<len(d) else b'')
    for h in res.get(t,[])[:20]:
        print('   %08x %s %s %s'%h)
EOF
