import ghidra.app.script.GhidraScript;
import ghidra.program.model.address.*;
import ghidra.program.model.lang.Register;
import ghidra.program.model.listing.*;
import ghidra.app.cmd.disassemble.DisassembleCommand;
import ghidra.app.decompiler.*;
import java.math.BigInteger;

public class Dump extends GhidraScript {
    public void run() throws Exception {
        Register tmode = currentProgram.getLanguage().getRegister("TMode");
        AddressSpace sp = currentProgram.getAddressFactory().getDefaultAddressSpace();
        Address cstart = sp.getAddress(0x1000);
        Address cend = sp.getAddress(0x2a0000);
        if (tmode != null)
            currentProgram.getProgramContext().setValue(tmode, cstart, cend, BigInteger.ONE);
        long[] addrs = {0x251eeL,0x222b0L,0x25a8eL,0x30e92L,0xc4beL,0x358faL,0x23c06L,0x27dfcL};
        DecompInterface di = new DecompInterface();
        di.toggleCCode(true);
        di.openProgram(currentProgram);
        for (long a : addrs) {
            Address ad = sp.getAddress(a);
            DisassembleCommand cmd = new DisassembleCommand(ad, null, true);
            cmd.applyTo(currentProgram, monitor);
            Function f = getFunctionAt(ad);
            if (f == null) { f = createFunction(ad, null); }
            println("==== FUNC " + Long.toHexString(a) + " => " + (f==null?"null":f.getName()));
            if (f == null) continue;
            DecompileResults res = di.decompileFunction(f, 120, monitor);
            if (res != null && res.decompileCompleted())
                println(res.getDecompiledFunction().getC());
            else
                println("DECOMP FAIL " + (res==null?"null":res.getErrorMessage()));
        }
    }
}
