import ghidra.app.script.GhidraScript;
import ghidra.program.model.address.*;
import ghidra.program.model.listing.*;
import ghidra.program.model.symbol.*;
import ghidra.app.decompiler.*;
import ghidra.program.model.mem.*;

public class DumpHal extends GhidraScript {
    public void run() throws Exception {
        SymbolTable st = currentProgram.getSymbolTable();
        SymbolIterator it = st.getAllSymbols(true);
        DecompInterface di = new DecompInterface(); di.toggleCCode(true); di.openProgram(currentProgram);
        int n=0;
        while (it.hasNext() && n < 40) {
            Symbol s = it.next();
            String nm = s.getName();
            if (nm.equals("exynos_v4l2_s_input") || nm.equals("exynos_v4l2_s_ctrl")) {
                println("SYM " + nm + " @ " + s.getAddress());
                ReferenceIterator ri = currentProgram.getReferenceManager().getReferencesTo(s.getAddress());
                while (ri.hasNext()) {
                    Reference r = ri.next();
                    Address from = r.getFromAddress();
                    Function f = getFunctionContaining(from);
                    println("  REF from " + from + " func=" + (f==null?"null":f.getName()));
                    // disassemble a window around the call site
                    Address start = from.subtract(24); if (start.getOffset()<0) start=from;
                    for (int k=0;k<16;k++) {
                        Address a = start.add(k*4);
                        try { println("    " + a + ": " + currentProgram.getListing().getInstructionAt(a)); } catch(Exception e){}
                    }
                    if (f != null) {
                        DecompileResults res = di.decompileFunction(f, 90, monitor);
                        if (res != null && res.decompileCompleted()) {
                            String c = res.getDecompiledFunction().getC();
                            println("---- C for " + f.getName());
                            println(c.length()>6000? c.substring(0,6000): c);
                        }
                    }
                    n++;
                }
            }
        }
    }
}
EOF
