cat > /tmp/ghscripts/FindStr.java <<'EOF'
import ghidra.app.script.GhidraScript;
import ghidra.program.model.address.*;
import ghidra.program.model.listing.*;
import ghidra.program.model.symbol.*;
import ghidra.program.model.data.*;
import ghidra.app.decompiler.*;

public class FindStr extends GhidraScript {
    public void run() throws Exception {
        String[] needles = {"m_startPreviewInternal", "startPreview", "m_startSensor", "m_setInput"};
        DecompInterface di = new DecompInterface(); di.toggleCCode(true); di.openProgram(currentProgram);
        java.util.Set<Function> funcs = new java.util.LinkedHashSet<>();
        for (Address a = currentProgram.getMinAddress(); a != null; a = a.add(1)) {
            // too slow; skip
            break;
        }
        // iterate defined data for strings
        DataIterator dit = currentProgram.getListing().getDefinedData(true);
        while (dit.hasNext()) {
            Data d = dit.next();
            if (d.getValue() == null) continue;
            String v = d.getValue().toString();
            for (String n : needles) {
                if (v.equals(n) || v.contains(n)) {
                    ReferenceIterator ri = currentProgram.getReferenceManager().getReferencesTo(d.getAddress());
                    while (ri.hasNext()) {
                        Reference r = ri.next();
                        Function f = getFunctionContaining(r.getFromAddress());
                        if (f != null) { funcs.add(f); println("STR " + n + " (" + v + ") -> func " + f.getName() + " @" + f.getEntryPoint()); }
                    }
                }
            }
        }
        for (Function f : funcs) {
            println("==== C for " + f.getName() + " @" + f.getEntryPoint());
            DecompileResults res = di.decompileFunction(f, 120, monitor);
            if (res != null && res.decompileCompleted()) {
                String c = res.getDecompiledFunction().getC();
                println(c.length()>20000? c.substring(0,20000): c);
            }
        }
    }
}
EOF
