#define J7_GPF0_CON	0x139C0180
#define J7_GPC2_CON	0x139C0080

static void j7_i2c_pin(void __iomem *con, int pin, int out)
{
	u32 v = readl(con);
	v &= ~(0xf << (pin * 4));
	v |= (out ? 1 : 0) << (pin * 4);
	writel(v, con);
}

static void j7_i2c_dat(void __iomem *dat, int pin, int val)
{
	u32 v = readl(dat);
	if (val)
		v |= 1 << pin;
	else
		v &= ~(1 << pin);
	writel(v, dat);
}

static int j7_i2c_probe_at(u32 con_phys, int scl, int sda, u8 addr7)
{
	void __iomem *con = ioremap(con_phys, 8);
	void __iomem *dat;
	u32 save;
	u8 addr = addr7 << 1;
	int i, ack;

	if (!con)
		return -1;
	dat = con + 4;
	save = readl(con);

