	j7_i2c_pin(con, sda, 0);
	udelay(2);
	j7_i2c_dat(dat, scl, 1);
	udelay(5);
	ack = (readl(dat) >> sda) & 1;
	j7_i2c_dat(dat, scl, 0);
	udelay(2);

	j7_i2c_pin(con, sda, 1);
	j7_i2c_dat(dat, sda, 0);
	udelay(2);
	j7_i2c_dat(dat, scl, 1);
	udelay(5);
	j7_i2c_dat(dat, sda, 1);
	udelay(5);
	j7_i2c_pin(con, scl, 1);
	j7_i2c_pin(con, sda, 1);
	j7_i2c_dat(dat, scl, 1);
	j7_i2c_dat(dat, sda, 1);

