int fimc_is_ischain_power(struct fimc_is_device_ischain *device, int on)
{
	int ret = 0;
	u32 val;
	struct device *dev;
	struct fimc_is_core *core;

	BUG_ON(!device);
	BUG_ON(!device->interface);

	dev = &device->pdev->dev;
	core = (struct fimc_is_core *)platform_get_drvdata(device->pdev);

	if (on) {
		/* 2. FIMC-IS local power enable */
#if defined(CONFIG_PM_RUNTIME)
		int rpm_ret;
		mdbgd_ischain("pm_runtime_suspended = %d\n", device, pm_runtime_suspended(dev));
		rpm_ret = pm_runtime_get_sync(dev);
		if (rpm_ret < 0)
			err("pm_runtime_get_sync() return error: %d", rpm_ret);
#else
		fimc_is_ischain_runtime_resume(dev);
		info("%s(%d) - fimc_is runtime resume complete\n", __func__, on);
#endif

#ifdef CONFIG_USE_VENDER_FEATURE
#ifdef CONFIG_COMPANION_USE
		if (!test_bit(FIMC_IS_COMPANION_S_INPUT, &core->companion.state))
#endif
		{
			ret = fimc_is_sec_run_fw_sel(dev, core->current_position);
			if (ret) {
				err("fimc_is_sec_run_fw_sel is fail(%d)", ret);
				goto p_err;
			}
		}

		{
			/* run_fw_sel() reads the module EEPROM and then powers the
			 * sensor rails down again; the firmware opens the sensor
			 * itself and needs them on.  Re-run the ON scenario so the
			 * reset is released, the rails are up and the MCLK pin is
			 * in function 0 (pin0).  Do NOT select pin1 here: it maps
			 * MCLK to input and the sensor then NACKs every transfer. */
			struct fimc_is_module_enum *module = NULL;
			int sret = fimc_is_sensor_g_module(
				&core->sensor[core->current_position], &module);
			if (!sret && module && module->pdata) {
				if (module->pdata->gpio_cfg) {
					int aret = module->pdata->gpio_cfg(module->pdev,
						SENSOR_SCENARIO_NORMAL, GPIO_SCENARIO_ON);
					info("sensor rails+pins on before FW boot: %d\n", aret);
					j7_pad_test(J7_GPF0_CON, 1);
					info("j7 eeprom probes: rear58(gpc2 3/2)=%d front10(gpf0 3/2)=%d\n",
					     j7_i2c_probe_at(J7_GPC2_CON, 3, 2, 0x58),
					     j7_i2c_probe_at(J7_GPF0_CON, 3, 2, 0x10));
					info("j7 sensor probes: ch0 5a(0/1)=%d 5a(1/0)=%d 20(0/1)=%d\n",
					     j7_i2c_probe_at(J7_GPF0_CON, 0, 1, 0x5a),
					     j7_i2c_probe_at(J7_GPF0_CON, 1, 0, 0x5a),
					     j7_i2c_probe_at(J7_GPF0_CON, 0, 1, 0x20));
					{
						const char *rails[] = {
							"VDD_CAM_SENSOR_A2P8",
							"VDD_CAM_1P2",
							"VDDIO_1.8V_CAM",
							"VDDAF_2.8V_CAM",
						};
						int ri;
						for (ri = 0; ri < 4; ri++) {
							struct regulator *reg =
								regulator_get(module->pdev, rails[ri]);
							if (IS_ERR(reg)) {
								info("j7 rail %s get=%ld\n", rails[ri], PTR_ERR(reg));
								continue;
							}
							info("j7 rail %s en=%d uv=%d\n", rails[ri],
							     regulator_is_enabled(reg),
							     regulator_get_voltage(reg));
							regulator_put(reg);
						}
					}
					if (module->pdata->sensor_i2c_ch == 0) {
						int rst = 148, gr;
						info("j7 reset148 before=%d\n", gpio_get_value(rst));
						gr = gpio_request_one(rst, GPIOF_OUT_INIT_LOW, "j7rst");
						info("j7 reset request=%d\n", gr);
						if (!gr) {
							udelay(2000);
							gpio_set_value(rst, 1);
							udelay(10000);
							info("j7 reset148 forced=%d ack5a=%d ack20=%d\n",
							     gpio_get_value(rst),
							     j7_i2c_probe_at(J7_GPF0_CON, 0, 1, 0x5a),
							     j7_i2c_probe_at(J7_GPF0_CON, 0, 1, 0x20));
							gpio_free(rst);
						}
					}
					{
						struct fimc_is_module_enum *mf = NULL;
						if (!fimc_is_sensor_g_module(&core->sensor[SENSOR_POSITION_FRONT], &mf) &&
						    mf && mf->pdata) {
							int fret = 0, fret2 = 0, mr, frst = 147;
							if (mf->pdata->gpio_cfg) {
								fret = mf->pdata->gpio_cfg(mf->pdev,
									SENSOR_SCENARIO_NORMAL, GPIO_SCENARIO_ON);
								udelay(10000);
							}
							mr = gpio_request_one(frst, GPIOF_OUT_INIT_LOW, "j7frst");
							if (!mr) {
								udelay(2000);
								gpio_set_value(frst, 1);
								udelay(10000);
							}
							info("j7 FRONT power=%d rst=%d lvl=%d ack20(2/3)=%d ack20(3/2)=%d\n",
							     fret, mr, gpio_get_value(frst),
							     j7_i2c_probe_at(J7_GPF0_CON, 2, 3, 0x20),
							     j7_i2c_probe_at(J7_GPF0_CON, 3, 2, 0x20));
							if (!mr)
								gpio_free(frst);
							if (mf->pdata->gpio_cfg)
								fret2 = mf->pdata->gpio_cfg(mf->pdev,
									SENSOR_SCENARIO_NORMAL, GPIO_SCENARIO_OFF);
							info("j7 FRONT power off=%d\n", fret2);
						} else {
							info("j7 FRONT module lookup failed\n");
						}
					}
					if (module->pdata->sensor_i2c_ch != 0)
						info("j7 sensor probes: ch1 20(2/3)=%d 20(3/2)=%d\n",
						     j7_i2c_probe_at(J7_GPF0_CON, 2, 3, 0x20),
						     j7_i2c_probe_at(J7_GPF0_CON, 3, 2, 0x20));
				}
			} else {
				info("sensor power lookup failed (%d)\n", sret);
			}
		}



