static int ktd2692_parse_dt(struct device *dev,
                                struct ktd2692_platform_data *pdata)
{
	struct device_node *dnode = dev->of_node;
	int ret = 0;

	/* Defulat Value */
	pdata->LVP_Voltage = KTD2692_DISABLE_LVP;
	pdata->flash_timeout = KTD2692_TIMER_1049ms;	/* default */
	pdata->min_current_value = KTD2692_MIN_CURRENT_240mA;
	pdata->movie_current_value = KTD2692_MOVIE_CURRENT5;
	pdata->flash_current_value = KTD2692_FLASH_CURRENT16;
	pdata->mode_status = KTD2692_DISABLES_MOVIE_FLASH_MODE;

	/* get gpio */
	pdata->flash_control = of_get_named_gpio(dnode, "flash_control", 0);
	if (!gpio_is_valid(pdata->flash_control)) {
		dev_err(dev, "failed to get flash_control\n");
		return -1;
	}

	return ret;
}

static int ktd2692_probe(struct platform_device *pdev)
{
	struct ktd2692_platform_data *pdata;
	int ret = 0;

	if (pdev->dev.of_node) {
		pdata = devm_kzalloc(&pdev->dev, sizeof(*pdata), GFP_KERNEL);
		if (!pdata) {
			dev_err(&pdev->dev, "Failed to allocate memory\n");
			return -ENOMEM;
		}
		ret = ktd2692_parse_dt(&pdev->dev, pdata);
		if (ret < 0) {
			return -EFAULT;
		}
	} else {
	pdata = pdev->dev.platform_data;
		if (pdata == NULL) {
			return -EFAULT;
		}
	}

	global_ktd2692data = pdata;
	ktd2692_dev = &pdev->dev;

	LED_INFO("KTD2692_LED Probe\n");

#if defined(KTD2692_USE_FOR_FRONT)
	if (IS_ERR(flash_dev)) {
		LED_ERROR("Failed to access device(flash)!\n");
	}

	if (device_create_file(flash_dev, &dev_attr_front_flash) < 0) {
		LED_ERROR("failed to create device file, %s\n",
				dev_attr_front_flash.attr.name);
	}

	if (device_create_file(flash_dev, &dev_attr_front_torch_flash) < 0) {
		LED_ERROR("failed to create device file, %s\n",
				dev_attr_front_torch_flash.attr.name);
	}
#else
	flash_dev = device_create(camera_class, NULL, 0, NULL, "flash");
	if (IS_ERR(flash_dev)) {
		LED_ERROR("Failed to create device(flash)!\n");
	}

	if (device_create_file(flash_dev, &dev_attr_rear_flash) < 0) {
		LED_ERROR("failed to create device file, %s\n",
				dev_attr_rear_flash.attr.name);
	}

	if (device_create_file(flash_dev, &dev_attr_rear_torch_flash) < 0) {
		LED_ERROR("failed to create device file, %s\n",
				dev_attr_rear_torch_flash.attr.name);
	}
#endif
	spin_lock_init(&pdata->int_lock);

	return 0;
}
static int __devexit ktd2692_remove(struct platform_device *pdev)
{
#if defined(KTD2692_USE_FOR_FRONT)
	device_remove_file(flash_dev, &dev_attr_front_flash);
	device_remove_file(flash_dev, &dev_attr_front_torch_flash);
#else
	device_remove_file(flash_dev, &dev_attr_rear_flash);
	device_remove_file(flash_dev, &dev_attr_rear_torch_flash);
#endif
	device_destroy(camera_class, 0);
	class_destroy(camera_class);

	return 0;
}

