	int ret;
#endif

	pr_debug("Entered %s\n", __func__);

	if (of_property_read_u32(np, dma_prop_addr[stream], &val))
		return -ENOMEM;
	dma_addr = (dma_addr_t)val;

	if (of_property_read_u32(np, dma_prop_size[stream], &val))
		return -ENOMEM;
