		ret = iommu_map(domain, dma_addr, dma_buf_pa, size, 0);
		if (ret) {
			dma_free_coherent(pcm->card->dev, size,
						buf->area, dma_buf_pa);
			pr_err("%s: Failed to iommu_map: %d\n", __func__, ret);
			return -ENOMEM;
		}

		di->iova = buf->addr;
		di->pa = dma_buf_pa;
		di->va = buf->area;
		list_add(&di->node, &iova_list);

