		regulator_enable(gps_vdd);
	} else {
		pr_err("[GPS] failed to get vdd_ldo10: %ld\n", PTR_ERR(gps_vdd));
		gps_vdd = NULL;
	}

	return 0;

err_sec_device_create:
	sec_device_destroy(gps_dev->devt);
	return ret;
}

