/* GPS rail: vdd_ldo10 (1.05 V) is off at boot on this board.
 * Resolve it through the GPS DT node's "vdd_ldo10-supply" property.
 */
if (root_node) {
	struct device_node *ldo10_node;
	struct device *gps_of_dev;

	ldo10_node = of_parse_phandle(root_node, "vdd_ldo10-supply", 0);
	if (ldo10_node) {
		gps_of_dev = bus_find_device_by_name(&platform_bus_type,
				NULL, "s2mpu03-pmic");
		if (gps_of_dev) {
			gps_vdd = devm_regulator_get(gps_of_dev, "vdd_ldo10");
			if (!IS_ERR(gps_vdd)) {
				regulator_set_voltage(gps_vdd, 1050000, 1050000);
				regulator_enable(gps_vdd);
			} else {
				pr_err("[GPS] devm_regulator_get failed: %ld\n",
				       PTR_ERR(gps_vdd));
				gps_vdd = NULL;
			}
		} else {
			pr_err("[GPS] s2mpu03-pmic device not found\n");
		}
	} else {
		pr_err("[GPS] vdd_ldo10-supply phandle not found\n");
	}
}

return 0;

