#include <linux/sec_sysfs.h>

/* S2MPU03_REG_L10CTRL: LDO10 enable bits are [7:6] (0xC0).  The PMIC
 * init clears them when g3d_en is set, killing the GPS rail. */
#define S2MPU03_L10CTRL_REG	0x34
#define S2MPU03_L10_EN_MASK	0xC0

static struct device *gps_dev;
static unsigned int gps_pwr_on = 0;
static struct regulator *gps_vdd;

int check_gps_op(void)
{
	/* This pin is high when gps is working */
	int gps_is_running = gpio_get_value(gps_pwr_on);

	pr_debug("LPA : check_gps_op(%d)\n", gps_is_running);

	return gps_is_running;
}
EXPORT_SYMBOL(check_gps_op);

static int __init gps_bcm4752_init(void)
{
	int ret = 0;
	const char *gps_node = "samsung,exynos-bcm4752";

	struct device_node *root_node = NULL;

	gps_dev = sec_device_create(NULL, "gps");
	BUG_ON(!gps_dev);

	root_node = of_find_compatible_node(NULL, NULL, gps_node);
	if (!root_node) {
		WARN(1, "failed to get device node of bcm4752\n");
		ret = -ENODEV;
		goto err_sec_device_create;
	}


	gps_pwr_on = of_get_gpio(root_node, 0);
	if (!gpio_is_valid(gps_pwr_on)) {
		WARN(1, "Invalied gpio pin : %d\n", gps_pwr_on);
		ret = -ENODEV;
		goto err_sec_device_create;
	}

	if (gpio_request(gps_pwr_on, "GPS_PWR_EN")) {
		WARN(1, "fail to request gpio(GPS_PWR_EN)\n");
		ret = -ENODEV;
		goto err_sec_device_create;
	}
	gpio_direction_output(gps_pwr_on, 0);
	gpio_export(gps_pwr_on, 1);
	gpio_export_link(gps_dev, "GPS_PWR_EN", gps_pwr_on);

	/* GPS rail: vdd_ldo10 (1.05 V) is off at boot on this board.
	 * The keep-stock-DTB rule means no DT supply phandle is available,
	 * so resolve the regulator by its kernel name (matches rdev name).
	 */
	gps_vdd = regulator_get(NULL, "vdd_ldo10");
	if (IS_ERR(gps_vdd)) {
		pr_err("[GPS] regulator_get(vdd_ldo10) failed: %ld\n",
		       PTR_ERR(gps_vdd));
		gps_vdd = NULL;
	} else {
		int eret = regulator_set_voltage(gps_vdd, 1050000, 1050000);
		if (eret)
			pr_err("[GPS] set_voltage failed: %d\n", eret);
		eret = regulator_enable(gps_vdd);
		if (eret)
			pr_err("[GPS] enable failed: %d\n", eret);
		else
			pr_info("[GPS] vdd_ldo10 enabled\n");
	}

	/* No stock gpsd here: assert the GPS power-enable pin ourselves */
	gpio_set_value(gps_pwr_on, 1);

	/* PMIC probe clears LDO10's enable bits when g3d_en=1 and leaves the
	 * rail gated by the buck4/G3D hardware sync (LDO_EFUSE[4]).  That
	 * stack never runs here, so drop the sync and enable LDO10 in
	 * software.
	 */
	{
		struct device *pmic;
		struct regmap *map = NULL;
		int rc = -ENODEV;

		pmic = bus_find_device_by_name(&platform_bus_type, NULL,
					       "s2mpu03-pmic");
		if (pmic) {
			map = dev_get_regmap(pmic, NULL);
			if (!map && pmic->parent)
				map = dev_get_regmap(pmic->parent, NULL);
		}
		if (map) {
			regmap_update_bits(map, 0x5B, 0x10, 0x00);
			rc = regmap_update_bits(map, S2MPU03_L10CTRL_REG,
						S2MPU03_L10_EN_MASK,
						S2MPU03_L10_EN_MASK);
		}
		pr_info("[GPS] LDO10 soft-enable rc=%d map=%p\n", rc, map);
	}

	pr_info("[GPS] GPS_PWR_EN asserted\n");

	return 0;

err_sec_device_create:
	sec_device_destroy(gps_dev->devt);
	return ret;
}

device_initcall(gps_bcm4752_init);

