/* Narrow privileged helper: kernel restart/poweroff via sysrq.
 * The bushybox reboot(2) path does not reset this SoC; sysrq 'b' does. */
#include <stdio.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdlib.h>
int main(int argc, char **argv)
{
	char c = 'b';
	if (argc > 1 && (!strcmp(argv[1], "poweroff") || !strcmp(argv[1], "o")))
		c = 'o';
	/* refuse to run with a dirty environment-controlled path */
	sync();
	int fd = open("/proc/sys/kernel/sysrq", O_WRONLY);
	if (fd < 0) { perror("sysrq"); return 1; }
	if (write(fd, "1", 1) != 1) { perror("sysrq enable"); }
	close(fd);
	fd = open("/proc/sysrq-trigger", O_WRONLY);
	if (fd < 0) { perror("trigger"); return 1; }
	write(fd, &c, 1);
	close(fd);
	return 0;
}
