/* GPU demo: EGL surfaceless + GLES2 (Panfrost) -> /dev/fb0 */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <math.h>
#include <time.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/fb.h>
#include <EGL/egl.h>
#include <GLES2/gl2.h>

static const char *VS =
"attribute vec2 p; uniform float a; varying vec3 c;\n"
"void main(){ float s=sin(a),k=cos(a);\n"
"  vec2 q=vec2(p.x*k-p.y*s, p.x*s+p.y*k);\n"
"  gl_Position=vec4(q*0.85,0.0,1.0);\n"
"  c=vec3(0.5+0.5*p.x, 0.2+0.6*p.y, 0.9-0.4*p.x); }\n";
static const char *FS =
"precision mediump float; varying vec3 c; void main(){ gl_FragColor=vec4(c,1.0); }\n";

static GLuint mk(GLenum t,const char*s){GLuint o=glCreateShader(t);glShaderSource(o,1,&s,0);glCompileShader(o);
  GLint ok=0;glGetShaderiv(o,GL_COMPILE_STATUS,&ok);if(!ok){char b[512];glGetShaderInfoLog(o,512,0,b);fprintf(stderr,"shader: %s\n",b);}return o;}

int main(int argc,char**argv){
  int W=256,H=256,seconds=argc>1?atoi(argv[1]):30;
  EGLDisplay d=eglGetDisplay(EGL_DEFAULT_DISPLAY);
  if(!eglInitialize(d,0,0)){fprintf(stderr,"eglInitialize failed\n");return 1;}
  EGLint cfga[]={EGL_SURFACE_TYPE,EGL_PBUFFER_BIT,EGL_RENDERABLE_TYPE,EGL_OPENGL_ES2_BIT,
                 EGL_RED_SIZE,8,EGL_GREEN_SIZE,8,EGL_BLUE_SIZE,8,EGL_ALPHA_SIZE,8,EGL_NONE};
  EGLConfig cfg;EGLint n;eglChooseConfig(d,cfga,&cfg,1,&n);
  EGLint pb[]={EGL_WIDTH,W,EGL_HEIGHT,H,EGL_NONE};
  EGLSurface s=eglCreatePbufferSurface(d,cfg,pb);
  EGLint cx[]={EGL_CONTEXT_CLIENT_VERSION,2,EGL_NONE};
  EGLContext c=eglCreateContext(d,cfg,EGL_NO_CONTEXT,cx);
  if(!eglMakeCurrent(d,s,s,c)){fprintf(stderr,"makeCurrent failed 0x%x\n",eglGetError());return 1;}
  printf("GL_RENDERER: %s\n",glGetString(GL_RENDERER));
  GLuint v=mk(GL_VERTEX_SHADER,VS),f=mk(GL_FRAGMENT_SHADER,FS);
  GLuint pr=glCreateProgram();glAttachShader(pr,v);glAttachShader(pr,f);glLinkProgram(pr);glUseProgram(pr);
  GLint pa=glGetAttribLocation(pr,"p"),ua=glGetUniformLocation(pr,"a");
  float verts[]={0,0.6f, -0.55f,-0.45f, 0.55f,-0.45f};
  GLuint vb;glGenBuffers(1,&vb);glBindBuffer(GL_ARRAY_BUFFER,vb);
  glBufferData(GL_ARRAY_BUFFER,sizeof verts,verts,GL_STATIC_DRAW);
  glEnableVertexAttribArray(pa);glVertexAttribPointer(pa,2,GL_FLOAT,GL_FALSE,0,0);

  int fb=open("/dev/fb0",O_RDWR); struct fb_var_screeninfo vi; struct fb_fix_screeninfo fi;
  if(fb<0){perror("/dev/fb0");return 1;}
  ioctl(fb,FBIOGET_VSCREENINFO,&vi); ioctl(fb,FBIOGET_FSCREENINFO,&fi);
  int FW=vi.xres,FH=vi.yres,BPP=vi.bits_per_pixel/8;
  size_t fbsz=(size_t)fi.line_length*FH;
  unsigned char *fbp=mmap(0,fbsz,PROT_READ|PROT_WRITE,MAP_SHARED,fb,0);
  printf("fb %dx%d %dbpp stride %d\n",FW,FH,vi.bits_per_pixel,fi.line_length);

  unsigned char *px=malloc(W*H*4), *scaled=malloc((size_t)fi.line_length*FH);
  memset(scaled,0,(size_t)fi.line_length*FH);
  int dw=FH*3/4, dh=FH*3/4, ox=(FW-dw)/2, oy=(FH-dh)/2;
  for(int i=0;i<seconds*20;i++){
    glClearColor(0.05f,0.05f,0.12f,1); glClear(GL_COLOR_BUFFER_BIT);
    glUniform1f(ua, i*0.06f);
    glDrawArrays(GL_TRIANGLES,0,3);
    glReadPixels(0,0,W,H,GL_RGBA,GL_UNSIGNED_BYTE,px);
    /* scale into framebuffer, flip Y, RGBA->BGRA */
    for(int y=0;y<dh;y++){
      int sy=(H-1)-(y*H/dh);
      unsigned char *row=scaled+(size_t)(oy+y)*fi.line_length+ox*BPP;
      for(int x=0;x<dw;x++){
        unsigned char *sp=px+((size_t)sy*W+(x*W/dw))*4;
        row[x*BPP+0]=sp[2]; row[x*BPP+1]=sp[1]; row[x*BPP+2]=sp[0]; row[x*BPP+3]=0xff;
      }
    }
    memcpy(fbp,scaled,fbsz);
    usleep(50000);
  }
  printf("demo done: %d frames rendered on GPU\n", seconds*20);
  return 0;
}
EOF
